get_shopping_cart.code:
use WebCommander\Sdk\Resources\Settings\PageSettings\ShoppingCart;

$response = ShoppingCart::getShoppingCart($client);

$settings = $response->map['shopping_cart'];
echo 'Cart page thumbnails: ', $settings['cart_page']['show_product_thumbnail'] ? 'true' : 'false', PHP_EOL;
echo 'Flying cart: ', $settings['flying_cart']['enabled'] ? 'true' : 'false', PHP_EOL;

patch_shopping_cart.code:
use WebCommander\Sdk\Resources\Settings\PageSettings\ShoppingCart;

$response = ShoppingCart::patchShoppingCart($client, [
    'shopping_cart' => [
        'cart_page' => ['show_product_thumbnail' => true],
        'flying_cart' => ['save_cart' => true],
    ],
]);

$settings = $response->map['shopping_cart'];
echo $settings['cart_page']['show_product_thumbnail'] ? 'true' : 'false', PHP_EOL;
echo $settings['flying_cart']['save_cart'] ? 'true' : 'false', PHP_EOL;
